source_code_context:
#include <errno.h>
#include <stdbool.h>
#include <stdint.h>

enum rrc_state {
    UE_RRC_IDLE,
    UE_RRC_RESUME_PENDING,
    UE_RRC_CONNECTED
};

struct resume_complete {
    uint8_t transaction_id;
};

struct ue_ctx {
    enum rrc_state state;
    uint8_t resume_transaction_id;
    bool resume_timer_running;
    uint64_t last_activity_ms;
};

extern uint64_t monotonic_ms(void);
extern int send_nas_resume_ack(struct ue_ctx *ue);

int handle_rrc_resume_complete(struct ue_ctx *ue,
                               const struct resume_complete *msg)
{
    if (ue == NULL || msg == NULL) {
        return -EINVAL;
    }
    if (ue->state != UE_RRC_RESUME_PENDING) {
        return -EPROTO;
    }
    if (msg->transaction_id != ue->resume_transaction_id) {
        return -EPROTO;
    }

    ue->state = UE_RRC_CONNECTED;
    ue->resume_timer_running = false;
    ue->last_activity_ms = monotonic_ms();
    return send_nas_resume_ack(ue);
}
